export const EXTRA_PODCAST_EPISODES: PodcastEpisode[] = [
  {"id": "identities-gen-beliefs-and-values-4", "themeId": "identities", "title": "La librería de la abuela", "description": "Dos hermanos discuten si deben vender la librería que heredaron de su abuela o mantenerla abierta.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, Tomás, ya recibí otra oferta por la librería. Una cadena quiere comprar el local y convertirlo en una cafetería.\n\nTomás: ¿En serio? Pues yo no lo tengo tan claro. Para mí la librería es más que un negocio; es donde la abuela nos enseñó a leer.\n\nLucía: Lo sé, pero seamos realistas. Las ventas bajan cada año y tenemos deudas. Vender nos daría dinero para vivir tranquilos.\n\nTomás: El dinero es importante, claro, pero no lo es todo. Creo que el barrio necesita espacios como este, donde la gente se conoce y charla.\n\nLucía: Eso suena muy bonito, pero no se paga el alquiler con nostalgia. Yo creo que hay que ser práctico.\n\nTomás: Vale, pero hay otra opción. Podríamos organizar clubes de lectura y talleres para niños. Yo podría encargarme de eso los fines de semana.\n\nLucía: Mmm... Eso requeriría tiempo y yo tengo un trabajo nuevo en otra ciudad. No sé si podría ayudar.\n\nTomás: Entonces lo hablamos con calma. Pero te pido que no tomes la decisión solo por dinero.\n\nLucía: Tienes razón. Démosle una semana más.", "questions": [{"id": "identities-gen-beliefs-and-values-4-q1", "type": "true-false", "prompt": "Las ventas de la librería suben cada año.", "correctAnswer": "false", "justification": "Las ventas bajan cada año y tenemos deudas."}, {"id": "identities-gen-beliefs-and-values-4-q2", "type": "true-false", "prompt": "Para Tomás, la librería es solo un negocio.", "correctAnswer": "false", "justification": "Para mí la librería es más que un negocio; es donde la abuela nos enseñó a leer."}, {"id": "identities-gen-beliefs-and-values-4-q3", "type": "mcq", "prompt": "¿Qué propone Tomás para salvar la librería?", "correctAnswer": "Organizar clubes de lectura y talleres para niños", "options": ["Organizar clubes de lectura y talleres para niños", "Vender el local a una cadena de cafeterías", "Mudarse a otra ciudad con su hermana"]}, {"id": "identities-gen-beliefs-and-values-4-q4", "type": "short", "prompt": "¿Qué cree Tomás que necesita el barrio?", "correctAnswer": "espacios como este"}, {"id": "identities-gen-beliefs-and-values-4-q5", "type": "short", "prompt": "¿Dónde trabaja ahora Lucía?", "correctAnswer": "En otra ciudad"}]},
  {"id": "identities-gen-lifestyles-and-hobbies-1", "themeId": "identities", "title": "Palomas que siempre vuelven", "description": "Una presentadora de radio entrevista a un aficionado a la colombofilia que explica por qué cuida palomas mensajeras cada mañana y qué opina del futuro de su afición.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Rocío: Tomás, en nuestro programa de hoy hablamos de aficiones poco comunes. ¿Es verdad que usted se levanta a las cinco de la mañana para cuidar sus palomas?\n\nTomás: ¡Así es! Cada día les doy de comer y limpio el palomar antes de ir a trabajar. Mi abuelo empezó con esto y yo lo heredé, aunque al principio no me interesaba nada.\n\nRocío: ¿Y qué le engancha de este pasatiempo?\n\nTomás: Pues, sinceramente, lo que más me gusta es la emoción de las carreras. Soltamos las palomas a cientos de kilómetros y ellas vuelven solas a casa. Es casi mágico.\n\nRocío: Pero mucha gente dice que es una afición anticuada y que no tiene futuro.\n\nTomás: Pues yo no lo creo. Hay jóvenes en el club y cada vez hay más interés. Lo que pasa es que hace falta paciencia, porque las aves necesitan muchos cuidados y no es barato.\n\nRocío: ¿Y su familia le apoya?\n\nTomás: Mi mujer al principio se quejaba del olor, pero ahora hasta me acompaña los domingos a las competiciones. Eso sí, nunca he ganado el campeonato provincial, aunque algún día lo haré.", "questions": [{"id": "identities-gen-lifestyles-and-hobbies-1-q1", "type": "true-false", "prompt": "Las palomas de Tomás regresan solas a casa después de las carreras.", "correctAnswer": "true", "justification": "Soltamos las palomas a cientos de kilómetros y ellas vuelven solas a casa."}, {"id": "identities-gen-lifestyles-and-hobbies-1-q2", "type": "true-false", "prompt": "Tomás se interesó por las palomas desde que era niño.", "correctAnswer": "false", "justification": "Mi abuelo empezó con esto y yo lo heredé, aunque al principio no me interesaba nada."}, {"id": "identities-gen-lifestyles-and-hobbies-1-q3", "type": "mcq", "prompt": "¿Qué opina Tomás sobre la idea de que su afición no tiene futuro?", "correctAnswer": "No está de acuerdo, porque hay jóvenes interesados en la afición.", "options": ["No está de acuerdo, porque hay jóvenes interesados en la afición.", "Está de acuerdo, porque la afición es cada vez más anticuada.", "Piensa que lo mejor es abandonar la afición por lo caro que resulta."]}, {"id": "identities-gen-lifestyles-and-hobbies-1-q4", "type": "mcq", "prompt": "¿Por qué se levanta Tomás a las cinco de la mañana?", "correctAnswer": "Para cuidar a sus palomas se levanta muy temprano.", "options": ["Para cuidar a sus palomas se levanta muy temprano.", "Para entrenar en un club de atletismo se levanta muy temprano.", "Para ir a la competición provincial se levanta muy temprano."]}, {"id": "identities-gen-lifestyles-and-hobbies-1-q5", "type": "short", "prompt": "¿Quién le enseñó a Tomás la afición a las palomas?", "correctAnswer": "su abuelo"}]},
  {"id": "identities-gen-language-and-identity-3", "themeId": "identities", "title": "Pan integral y acento", "description": "Un panadero español que vive en Róterdam conversa en un programa de radio sobre cómo el idioma y el acento influyen en su identidad y en la de su familia.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Lucía: Hoy hablamos con Tomás, que lleva doce años regentando una panadería en Róterdam. Tomás, cuéntanos, ¿en qué idioma piensas tú?\n\nTomás: Pues depende del día. Con mis clientes hablo neerlandés, pero en casa con mi mujer hablamos español y a veces mezclamos las dos cosas sin darnos cuenta.\n\nLucía: ¿Y no te sientes raro al cambiar de idioma?\n\nTomás: Al principio sí. Cuando llegué, me daba vergüenza equivocarme. Ahora me hace gracia. Mi hija de seis años me corrige cuando digo \"pan integral\" en vez de la palabra holandesa, y se parte de risa.\n\nLucía: ¿Crees que perder el acento de tu tierra te quita parte de tu identidad?\n\nTomás: Para nada. Yo sigo siendo de Cádiz aunque mi acento ya suene a mezcla. Lo que sí me preocupa es que mi hija no quiera hablar español con los abuelos.\n\nLucía: ¿Entonces qué le recomendarías a un padre en tu situación?\n\nTomás: Que no tenga miedo de que se mezclen los idiomas. Lo importante es que el niño sepa de dónde viene, y eso se transmite con cariño, no con exámenes.", "questions": [{"id": "identities-gen-language-and-identity-3-q1", "type": "true-false", "prompt": "Tomás habla neerlandés con sus clientes y español en casa.", "correctAnswer": "true", "justification": "Con mis clientes hablo neerlandés, pero en casa con mi mujer hablamos español"}, {"id": "identities-gen-language-and-identity-3-q2", "type": "mcq", "prompt": "¿Qué le preocupa a Tomás?", "correctAnswer": "que su hija no quiera hablar español con los abuelos", "options": ["que su hija no quiera hablar español con los abuelos", "que sus clientes no entiendan el neerlandés", "que su acento sea demasiado fuerte"]}, {"id": "identities-gen-language-and-identity-3-q3", "type": "true-false", "prompt": "Tomás opina que perder el acento le quita parte de su identidad.", "correctAnswer": "false", "justification": "Para nada. Yo sigo siendo de Cádiz aunque mi acento ya suene a mezcla."}, {"id": "identities-gen-language-and-identity-3-q4", "type": "short", "prompt": "¿Qué recomienda Tomás a un padre en su situación?", "correctAnswer": "no tener miedo"}, {"id": "identities-gen-language-and-identity-3-q5", "type": "short", "prompt": "¿Qué hace la hija de Tomás cuando él dice \"pan integral\"?", "correctAnswer": "lo corrige"}]},
  {"id": "identities-gen-health-and-well-being-2", "themeId": "identities", "title": "Baño de bosque", "description": "Dos amigos conversan sobre una sesión de baño de bosque en el parque y tienen opiniones muy distintas sobre sus beneficios para la salud.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Marta: Oye, ¿sabes que el sábado hay una sesión de \"baño de bosque\" en el parque de la sierra?\n\nJulián: ¿Baño de bosque? Suena a chorrada de esas que se ponen de moda en Instagram.\n\nMarta: Pues no es tan raro. Consiste en caminar despacio y fijarte en los sonidos y los olores. Mi hermana lo probó el año pasado y llegó a casa con la cabeza mucho más despejada.\n\nJulián: Bueno, puede ser. Tengo estrés del trabajo, pero me cuesta creer que un paseo cambie tanto.\n\nMarta: Pues yo creo que sí. Antes estaba agobiadísima y ahora, aunque no lo hago todos los días, me sienta de maravilla.\n\nJulián: Vale, me convences a medias. ¿Hay que llevar algo especial?\n\nMarta: Solo zapatillas cómodas y agua. Y ojo, el guía pide que apagues el móvil durante toda la sesión. Yo creo que eso es lo mejor de todo.\n\nJulián: Eso sí que me costaría, mi móvil es mi vida. Pero si me prometes que no me vas a hacer abrazar a ningún árbol, voy contigo.\n\nMarta: ¡Trato hecho! No hace falta abrazar nada... aunque el guía sí lo sugirió.", "questions": [{"id": "identities-gen-health-and-well-being-2-q1", "type": "true-false", "prompt": "Julián opina que el baño de bosque es una moda sin fundamento.", "correctAnswer": "true", "justification": "Suena a chorrada de esas que se ponen de moda en Instagram."}, {"id": "identities-gen-health-and-well-being-2-q2", "type": "true-false", "prompt": "Marta considera que desconectar el móvil es lo mejor de la sesión.", "correctAnswer": "true", "justification": "Yo creo que eso es lo mejor de todo."}, {"id": "identities-gen-health-and-well-being-2-q3", "type": "mcq", "prompt": "¿Qué debe hacer la gente durante la sesión según el guía?", "correctAnswer": "Apagar el móvil durante toda la sesión", "options": ["Apagar el móvil durante toda la sesión", "Llevar una cámara de fotos", "Caminar muy rápido"]}, {"id": "identities-gen-health-and-well-being-2-q4", "type": "short", "prompt": "¿Qué actividad propone Marta a Julián?", "correctAnswer": "baño de bosque"}, {"id": "identities-gen-health-and-well-being-2-q5", "type": "short", "prompt": "¿Qué condición pone Julián para acompañar a Marta?", "correctAnswer": "no abrazar árboles"}]},
  {"id": "identities-gen-childhood-and-adolescence-5", "themeId": "identities", "title": "Voces del coro", "description": "Dos antiguos miembros de un coro infantil recuerdan cómo esa experiencia marcó su infancia y su forma de ser hoy.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: ¡Tomás, cuánto tiempo! Mira, encontré la carpeta del coro del colegio. Cantábamos en todas las fiestas del pueblo.\n\nTomás: Y yo odiaba los ensayos de los martes. Me aburrían muchísimo y el director nos obligaba a llegar a las siete en punto.\n\nLucía: A mí me encantaban. Era lo único que hacía con gente de todas las edades.\n\nTomás: Puede ser, pero yo no lo veía así. Ahora reconozco que aprendí disciplina. Lo que sí me sorprende es que todavía me sé la letra de casi todas las canciones.\n\nLucía: Lo curioso es que nunca tuve miedo de cantar delante de la gente. Hoy doy presentaciones en el trabajo sin pensarlo dos veces.\n\nTomás: Yo, en cambio, tardé años en dejar de sentir vergüenza. Creo que el coro me hizo mejor persona, aunque no me gustara en su momento.\n\nLucía: Totalmente de acuerdo. ¿Y sabes qué? Deberíamos volver a cantar juntos algún día.\n\nTomás: Vale, pero con una condición: nada de martes a las siete.", "questions": [{"id": "identities-gen-childhood-and-adolescence-5-q1", "type": "true-false", "prompt": "Tomás disfrutaba mucho de los ensayos del coro.", "correctAnswer": "false", "justification": "Y yo odiaba los ensayos de los martes."}, {"id": "identities-gen-childhood-and-adolescence-5-q2", "type": "true-false", "prompt": "Lucía trabaja hoy dando presentaciones.", "correctAnswer": "true", "justification": "Hoy doy presentaciones en el trabajo sin pensarlo dos veces."}, {"id": "identities-gen-childhood-and-adolescence-5-q3", "type": "mcq", "prompt": "¿Qué opina Tomás del coro en la actualidad?", "correctAnswer": "Que el coro lo ayudó a ser mejor persona aunque no le gustara entonces", "options": ["Que el coro lo ayudó a ser mejor persona aunque no le gustara entonces", "Que el coro fue una pérdida de tiempo", "Que prefiere no hablar de su experiencia en el coro"]}, {"id": "identities-gen-childhood-and-adolescence-5-q4", "type": "mcq", "prompt": "¿Por qué le encantaba el coro a Lucía?", "correctAnswer": "Porque podía convivir con personas de todas las edades", "options": ["Porque podía convivir con personas de todas las edades", "Porque ganaba premios en todos los concursos", "Porque el director le daba dinero"]}, {"id": "identities-gen-childhood-and-adolescence-5-q5", "type": "short", "prompt": "¿Qué propone Lucía al final de la conversación?", "correctAnswer": "volver a cantar juntos"}]},
  {"id": "experiences-gen-travel-and-tourism-1", "themeId": "experiences", "title": "Una semana entre olivos", "description": "Dos amigos comentan la experiencia de Tomás como voluntario en una finca de olivos de Jaén.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Tomás, ¿qué tal la semana en el olivar? Nunca te imaginé recogiendo aceitunas.\n\nTomás: Pues fue muy distinto a lo que esperaba. Pensaba pasar el día en una piscina, pero nos levantábamos a las seis de la mañana.\n\nLucía: ¡Qué madrugón! ¿Y en qué consistía el trabajo?\n\nTomás: Recogíamos aceitunas a mano con redes en el suelo. Al principio me dolía la espalda horrible. Eso sí, los dueños cocinaban unas migas buenísimas al mediodía.\n\nLucía: Suena agotador, pero me parece un plan bonito para desconectar. ¿Lo recomendarías?\n\nTomás: Sinceramente, sí, aunque no es para todo el mundo. Si buscas lujo, no es tu sitio. Lo que más me gustó fue conocer gente de Alemania y Japón, y hablar en español todo el tiempo.\n\nLucía: Pues creo que el turismo así es mucho más auténtico que sacarse fotos en la playa.\n\nTomás: Sí, aprendí a distinguir una aceituna verde de una negra, y a no quejarme tanto del calor. Bueno, eso último lo sigo intentando.\n\nLucía: Jaja, ¡me alegro! La próxima vez me apunto contigo.", "questions": [{"id": "experiences-gen-travel-and-tourism-1-q1", "type": "true-false", "prompt": "Tomás sabía desde el principio que tendría que levantarse muy temprano cada día.", "correctAnswer": "false", "justification": "Pensaba pasar el día en una piscina, pero nos levantábamos a las seis de la mañana."}, {"id": "experiences-gen-travel-and-tourism-1-q2", "type": "true-false", "prompt": "Los dueños de la finca preparaban la comida del mediodía para los voluntarios.", "correctAnswer": "true", "justification": "Eso sí, los dueños cocinaban unas migas buenísimas al mediodía."}, {"id": "experiences-gen-travel-and-tourism-1-q3", "type": "mcq", "prompt": "¿Qué opina Lucía sobre este tipo de turismo?", "correctAnswer": "Que es más auténtico que sacarse fotos en la playa", "options": ["Que es más auténtico que sacarse fotos en la playa", "Que es demasiado caro para la mayoría de la gente", "Que es aburrido y poco interesante"]}, {"id": "experiences-gen-travel-and-tourism-1-q4", "type": "short", "prompt": "¿Qué parte del cuerpo le dolía a Tomás al principio?", "correctAnswer": "la espalda"}, {"id": "experiences-gen-travel-and-tourism-1-q5", "type": "short", "prompt": "¿Qué idioma practicaba Tomás todo el tiempo con los demás participantes?", "correctAnswer": "español"}]},
  {"id": "identities-gen-lifestyles-and-hobbies-6", "themeId": "identities", "title": "Abejas en la azotea", "description": "Dos vecinos conversan sobre su afición a la apicultura urbana en la azotea de su edificio en Valencia.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Lucía: ¡Hola, Tomás! Ya subí a la azotea. ¿Cómo están las abejas hoy?\n\nTomás: Pues bastante bien, aunque una colmena se me está enjambrando. Es un follón, la verdad.\n\nLucía: ¿En serio? Yo pensaba que tener abejas en la ciudad era una tontería, pero me estoy enganchando.\n\nTomás: Pues a mí me parece una afición buenísima. Te obliga a desconectar del móvil y a estar al aire libre. Además, la miel que sacamos el año pasado estaba riquísima.\n\nLucía: Lo que más me gusta es que los vecinos ya no se quejan. Al principio tenían miedo, pero ahora nos traen tarros para la miel.\n\nTomás: Sí, pero hay que ser paciente. Yo al principio me picaron tres veces y casi me rindo.\n\nLucía: Bueno, el sábado vamos a un curso en el centro cívico. ¿Te apuntas?\n\nTomás: Claro, aunque no me hace mucha gracia madrugar los fines de semana.\n\nLucía: Venga, no seas gruñón. Además, si la cosecha sale bien, te regalo un tarro de miel de azahar.\n\nTomás: Vale, me has convencido. Pero que conste que lo hago por la miel.", "questions": [{"id": "identities-gen-lifestyles-and-hobbies-6-q1", "type": "true-false", "prompt": "Lucía piensa que tener abejas en la ciudad es una tontería.", "correctAnswer": "false", "justification": "Yo pensaba que tener abejas en la ciudad era una tontería, pero me estoy enganchando."}, {"id": "identities-gen-lifestyles-and-hobbies-6-q2", "type": "true-false", "prompt": "Los vecinos ya no se quejan de las abejas.", "correctAnswer": "true", "justification": "Lo que más me gusta es que los vecinos ya no se quejan."}, {"id": "identities-gen-lifestyles-and-hobbies-6-q3", "type": "mcq", "prompt": "¿Qué le molesta a Tomás del curso del sábado?", "correctAnswer": "Tiene que madrugar los fines de semana.", "options": ["Tiene que madrugar los fines de semana.", "Tiene miedo de las abejas.", "No tiene dinero para el curso."]}, {"id": "identities-gen-lifestyles-and-hobbies-6-q4", "type": "short", "prompt": "¿Qué le promete Lucía a Tomás si la cosecha sale bien?", "correctAnswer": "miel de azahar"}, {"id": "identities-gen-lifestyles-and-hobbies-6-q5", "type": "short", "prompt": "¿Qué opina Tomás de la apicultura?", "correctAnswer": "una afición buenísima"}]},
  {"id": "experiences-gen-celebrations-and-holidays-2", "themeId": "experiences", "title": "El concurso de tortilla", "description": "Dos vecinos comentan las fiestas de su pueblo y el concurso de tortilla de patatas que se celebra durante ellas.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: ¡Ya están montando el escenario en la plaza! Las fiestas del pueblo empiezan el viernes, ¿te apuntas al concurso de tortilla?\n\nTomás: ¿Yo? Ni loco. Mi tortilla siempre queda aguada, y el año pasado la señora Remedios me miró como si hubiera cometido un crimen.\n\nLucía: Pues precisamente por eso deberías participar. Es un concurso sin tanta presión, lo importante es pasarlo bien y compartir.\n\nTomás: Eso dices tú, pero los premios son serios. El ganador se lleva un jamón entero.\n\nLucía: Sí, la gente se toma la competición muy en serio, pero a mí me parece lo mejor de las fiestas. Lo que más me gusta es que todos los vecinos se juntan, desde los niños hasta los abuelos.\n\nTomás: Tienes razón en eso. Este año, además, han cambiado el horario de la verbena, que empieza a las once de la noche. Yo creo que es demasiado tarde para los peques.\n\nLucía: Bueno, es que en verano aquí nadie se acuesta temprano. La música tradicional que tocan después es preciosa, aunque sea un poco ruidosa.\n\nTomás: Vale, vale. Me has convencido a medias. Si me ayudas a mejorar la receta, me apunto.", "questions": [{"id": "experiences-gen-celebrations-and-holidays-2-q1", "type": "true-false", "prompt": "A Tomás le sale siempre muy buena la tortilla.", "correctAnswer": "false", "justification": "Mi tortilla siempre queda aguada"}, {"id": "experiences-gen-celebrations-and-holidays-2-q2", "type": "true-false", "prompt": "Lucía piensa que el concurso no tiene tanta presión.", "correctAnswer": "true", "justification": "Es un concurso sin tanta presión"}, {"id": "experiences-gen-celebrations-and-holidays-2-q3", "type": "mcq", "prompt": "¿Qué es lo que más le gusta a Lucía de las fiestas?", "correctAnswer": "Que todos los vecinos se juntan", "options": ["Que todos los vecinos se juntan", "El jamón que se lleva el ganador", "El horario de la verbena"]}, {"id": "experiences-gen-celebrations-and-holidays-2-q4", "type": "true-false", "prompt": "Tomás considera que la verbena empieza demasiado tarde para los niños.", "correctAnswer": "true", "justification": "Yo creo que es demasiado tarde para los peques"}, {"id": "experiences-gen-celebrations-and-holidays-2-q5", "type": "short", "prompt": "¿Qué le pide Tomás a Lucía?", "correctAnswer": "mejorar la receta"}]},
  {"id": "experiences-gen-rites-of-passage-3", "themeId": "experiences", "title": "Las llaves del horno", "description": "Dos amigos comentan la primera noche en la que uno de ellos trabaja solo en una panadería de barrio.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Marina: Oye, Iván, ¿qué tal tu primera noche sola en la panadería? Me dijiste que el jefe te dio las llaves.\n\nIván: Sí, tío, flipante y agotador a la vez. Llegué a las tres de la mañana y ya tenía la masa fermentando desde la noche anterior. Lo más difícil fue encender el horno viejo, que tiene un truco.\n\nMarina: ¿Y te salió bien el pan?\n\nIván: Las barras salieron un poco pálidas, pero Don Remigio las probó y dijo que estaban \"aceptables\". Para él eso es un piropo.\n\nMarina: Jaja, entonces estás dentro. ¿Sientes que ya eres panadero de verdad?\n\nIván: Bueno, para mí fue como un examen de madurez. Antes me limitaba a amasar y a limpiar. Ahora decido yo cuándo sacar la fornada. Me da un poco de vértigo, la verdad.\n\nMarina: Pues a mí me parece increíble. Yo nunca me atrevería a levantarme a las tres de la mañana.\n\nIván: Ya, pero el olor del pan recién hecho compensa. Y los vecinos ya me saludan como \"el nuevo\".", "questions": [{"id": "experiences-gen-rites-of-passage-3-q1", "type": "true-false", "prompt": "Iván llegó a la panadería a las tres de la mañana.", "correctAnswer": "true", "justification": "Llegué a las tres de la mañana y ya tenía la masa fermentando desde la noche anterior."}, {"id": "experiences-gen-rites-of-passage-3-q2", "type": "true-false", "prompt": "Don Remigio considera que las barras de pan son excelentes.", "correctAnswer": "false", "justification": "Las barras salieron un poco pálidas, pero Don Remigio las probó y dijo que estaban \"aceptables\"."}, {"id": "experiences-gen-rites-of-passage-3-q3", "type": "mcq", "prompt": "¿Qué opina Marina sobre la primera noche de Iván?", "correctAnswer": "Le parece increíble", "options": ["Le parece increíble", "Le parece aburrido", "Le parece normal"]}, {"id": "experiences-gen-rites-of-passage-3-q4", "type": "short", "prompt": "¿Qué fue lo más difícil para Iván la primera noche?", "correctAnswer": "encender el horno viejo"}, {"id": "experiences-gen-rites-of-passage-3-q5", "type": "short", "prompt": "¿Qué sentimiento le produce a Iván la nueva responsabilidad?", "correctAnswer": "vértigo"}]},
  {"id": "experiences-gen-personal-stories-and-memories-5", "themeId": "experiences", "title": "La última noche del cine Imperial", "description": "Dos hermanos recuerdan la última función de un viejo cine de su pueblo y cómo, años después, decidieron devolverle vida a aquella tradición.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye Mateo, ¿te acuerdas de la última noche del cine Imperial?\n\nMateo: ¡Claro! Yo tenía unos nueve años. Mi abuelo nos llevó a ver una película de vaqueros, aunque ni siquiera sabía quién era el protagonista.\n\nLucía: Lo que más recuerdo es el olor a palomitas quemadas. El proyector se paró a mitad de la película y todo el mundo empezó a aplaudir.\n\nMateo: Sí, fue muy gracioso. Luego el dueño salió y dijo que el edificio se iba a convertir en un supermercado. Mi abuelo se puso triste.\n\nLucía: A mí me pareció una tontería que lloráramos por un local. Pero ahora, cuando paso por allí, me acuerdo de todo.\n\nMateo: Yo creo que no es una tontería. Esos lugares guardan muchas historias de la gente del barrio.\n\nLucía: Tienes razón. Por eso el año pasado organizamos una proyección en la plaza, con sillas de plástico y una sábana blanca.\n\nMateo: Fue un éxito. Vino casi todo el pueblo, y hasta el alcalde se quedó a ver el final.\n\nLucía: Lo mejor fue ver a mi abuelo otra vez sonriendo mientras sonaba la música de su película favorita.", "questions": [{"id": "experiences-gen-personal-stories-and-memories-5-q1", "type": "true-false", "prompt": "Al principio, Lucía pensaba que llorar por el cine era una tontería.", "correctAnswer": "true", "justification": "A mí me pareció una tontería que lloráramos por un local."}, {"id": "experiences-gen-personal-stories-and-memories-5-q2", "type": "true-false", "prompt": "El proyector se averió al empezar la película.", "correctAnswer": "false", "justification": "El proyector se paró a mitad de la película y todo el mundo empezó a aplaudir."}, {"id": "experiences-gen-personal-stories-and-memories-5-q3", "type": "mcq", "prompt": "¿Por qué se puso triste el abuelo de Mateo?", "correctAnswer": "Porque el edificio se iba a convertir en un supermercado.", "options": ["Porque el edificio se iba a convertir en un supermercado.", "Porque la película era muy aburrida.", "Porque había perdido las entradas."]}, {"id": "experiences-gen-personal-stories-and-memories-5-q4", "type": "short", "prompt": "¿Qué opina Mateo sobre los lugares como el cine?", "correctAnswer": "guardan muchas historias del barrio"}, {"id": "experiences-gen-personal-stories-and-memories-5-q5", "type": "short", "prompt": "¿Quién se quedó a ver el final de la proyección en la plaza?", "correctAnswer": "el alcalde"}]},
  {"id": "experiences-gen-migration-and-displacement-4", "themeId": "experiences", "title": "Bajo el agua", "description": "Dos primos hablan sobre las fotos antiguas de su abuela, que tuvo que abandonar su pueblo cuando se construyó un embalse.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, ¿viste las fotos que encontró mi abuela en la caja de zapatos? Son de su pueblo.\n\nMateo: Sí, las vi ayer. Es raro pensar que ese sitio ahora está debajo del agua.\n\nLucía: Cuando construyeron el embalse, ella tenía doce años. Le dieron una casa en la ciudad y nunca volvió a ver la iglesia.\n\nMateo: Yo creo que el gobierno debió consultar a la gente antes. No es justo decidir por todos sin preguntar.\n\nLucía: Al principio estaba enfadada, pero luego aprendió a querer su barrio nuevo. Dice que la vida no se para por una inundación.\n\nMateo: ¿Y si el próximo verano hacemos una excursión en barco hasta el embalse? Cuando baja el nivel del agua se ven las ruinas.\n\nLucía: ¡Buena idea! Aunque a ella le dará pena verlo otra vez.\n\nMateo: Puede ser, pero le gustaría contarnos cómo era la plaza y dónde jugaban de niños.\n\nLucía: Tienes razón. Esta noche le pregunto qué opina.", "questions": [{"id": "experiences-gen-migration-and-displacement-4-q1", "type": "true-false", "prompt": "La abuela tenía veinte años cuando construyeron el embalse.", "correctAnswer": "false", "justification": "Cuando construyeron el embalse, ella tenía doce años."}, {"id": "experiences-gen-migration-and-displacement-4-q2", "type": "true-false", "prompt": "Mateo opina que el gobierno debió consultar a la población antes de decidir.", "correctAnswer": "true", "justification": "Yo creo que el gobierno debió consultar a la gente antes."}, {"id": "experiences-gen-migration-and-displacement-4-q3", "type": "mcq", "prompt": "¿Qué sentimiento tuvo la abuela al principio, según Lucía?", "correctAnswer": "Estaba enfadada", "options": ["Estaba enfadada", "Estaba contenta", "Estaba indiferente"]}, {"id": "experiences-gen-migration-and-displacement-4-q4", "type": "mcq", "prompt": "¿Qué propone Mateo para el próximo verano?", "correctAnswer": "Una excursión en barco hasta el embalse", "options": ["Una excursión en barco hasta el embalse", "Un viaje en tren a la ciudad", "Una visita a la iglesia del pueblo"]}, {"id": "experiences-gen-migration-and-displacement-4-q5", "type": "short", "prompt": "¿Qué quiere hacer Lucía esta noche?", "correctAnswer": "Preguntarle a la abuela"}]},
  {"id": "human-ingenuity-gen-technology-and-innovation-1", "themeId": "human-ingenuity", "title": "Las colmenas conectadas", "description": "Dos amigos discuten sobre si un sensor conectado a las colmenas de un apicultor es una ayuda útil o una exageración.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, Andrés, ¿ya probaste el sensor que te instalaron en las colmenas?\n\nAndrés: Sí, y te juro que me tiene flipado. La aplicación me avisa en el móvil cuando la temperatura dentro de una colmena baja demasiado.\n\nLucía: Pues a mí me parece una exageración. Mi abuelo llevaba cuarenta años con abejas y nunca necesitó nada de eso.\n\nAndrés: Ya, pero tu abuelo no perdía media cosecha por un frío repentino. Este año nos salvó dos colmenas.\n\nLucía: Vale, lo reconozco, eso sí impresiona. Pero me preocupa que la gente deje de mirar las colmenas con sus propios ojos.\n\nAndrés: Esa es mi duda también. Yo sigo yendo cada semana, pero el sensor me da tranquilidad cuando estoy en el trabajo.\n\nLucía: ¿Y cuánto cuesta el aparato?\n\nAndrés: Unos ochenta euros por colmena, más la suscripción. No es barato, la verdad.\n\nLucía: Pues yo creo que la tecnología tiene que ayudar, no sustituir el oficio.\n\nAndrés: Totalmente de acuerdo. Mañana te enseño la app, a ver si te convences.", "questions": [{"id": "human-ingenuity-gen-technology-and-innovation-1-q1", "type": "true-false", "prompt": "La aplicación avisa cuando la temperatura de la colmena sube demasiado.", "correctAnswer": "true", "justification": "La aplicación me avisa en el móvil cuando la temperatura dentro de una colmena baja demasiado."}, {"id": "human-ingenuity-gen-technology-and-innovation-1-q2", "type": "true-false", "prompt": "Este año el sensor salvó dos colmenas.", "correctAnswer": "true", "justification": "Este año nos salvó dos colmenas."}, {"id": "human-ingenuity-gen-technology-and-innovation-1-q3", "type": "mcq", "prompt": "¿Qué opina Lucía sobre la tecnología en la apicultura?", "correctAnswer": "Que debe ayudar, no sustituir el oficio.", "options": ["Que debe ayudar, no sustituir el oficio.", "Que es demasiado cara para cualquier apicultor.", "Que el abuelo la usaba cada semana."]}, {"id": "human-ingenuity-gen-technology-and-innovation-1-q4", "type": "mcq", "prompt": "¿Cuánto cuesta el sensor por colmena?", "correctAnswer": "Unos ochenta euros.", "options": ["Unos ochenta euros.", "Unos ocho euros.", "Unos ochocientos euros."]}, {"id": "human-ingenuity-gen-technology-and-innovation-1-q5", "type": "short", "prompt": "¿Qué le da el sensor a Andrés cuando está en el trabajo?", "correctAnswer": "tranquilidad"}]},
  {"id": "experiences-gen-travel-and-tourism-6", "themeId": "experiences", "title": "Recogiendo aceitunas en Jaén", "description": "Dos amigos comentan una semana de turismo rural en Jaén, en la que participaron en la recogida de la aceituna.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, ¿te acuerdas de la semana que pasamos recogiendo aceitunas en Jaén? Yo pensaba que iba a ser un viaje tranquilo, pero ¡qué va!\n\nTomás: Ni me lo recuerdes. Me levantaba a las seis de la mañana y me dolía hasta la espalda. Pero fue de lo mejor del viaje.\n\nLucía: Eso sí. Lo que más me gustó fue la familia que nos acogió. La abuela nos enseñaba a preparar migas y no paraba de reírse de nuestro acento.\n\nTomás: Y el aceite recién salido de la almazara, buenísimo. Aunque el alojamiento era muy básico. El baño tenía una ducha que apenas daba agua caliente.\n\nLucía: Bueno, eso no me molestó tanto. Lo que sí me sorprendió es que el precio incluía el autobús desde Madrid y casi todo estaba bien organizado. Solo echo de menos más información antes.\n\nTomás: Yo creo que la gente debería saber que no es un viaje de lujo. Si buscas relax, mejor elige otra cosa. Pero si quieres algo auténtico, repetiría sin dudarlo.\n\nLucía: Totalmente de acuerdo. El año que viene quiero ir en la vendimia, a ver si hay uva en Rioja.", "questions": [{"id": "experiences-gen-travel-and-tourism-6-q1", "type": "true-false", "prompt": "Tomás se levantaba muy temprano durante la recogida de aceitunas.", "correctAnswer": "true", "justification": "Me levantaba a las seis de la mañana y me dolía hasta la espalda."}, {"id": "experiences-gen-travel-and-tourism-6-q2", "type": "true-false", "prompt": "Lucía se quejó de que la organización del viaje fue muy mala.", "correctAnswer": "false", "justification": "Lo que sí me sorprendió es que el precio incluía el autobús desde Madrid y casi todo estaba bien organizado."}, {"id": "experiences-gen-travel-and-tourism-6-q3", "type": "mcq", "prompt": "¿Qué opina Tomás sobre este viaje para las personas que buscan relax?", "correctAnswer": "Que no es adecuado para quien busca relax", "options": ["Que no es adecuado para quien busca relax", "Que es el viaje perfecto para descansar", "Que el alojamiento era de lujo"]}, {"id": "experiences-gen-travel-and-tourism-6-q4", "type": "short", "prompt": "¿Qué quiere hacer Lucía el año que viene?", "correctAnswer": "la vendimia"}, {"id": "experiences-gen-travel-and-tourism-6-q5", "type": "short", "prompt": "¿Qué les enseñaba la abuela a los dos amigos?", "correctAnswer": "preparar migas"}]},
  {"id": "human-ingenuity-gen-communication-online-3", "themeId": "human-ingenuity", "title": "El grupo que mueve el pueblo", "description": "Dos vecinos comentan cómo un grupo de WhatsApp ayuda a organizar el transporte escolar en una aldea de montaña.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Marina: Oye, Tomás, ¿te acuerdas del autobús escolar de Valdeluz? Se cancelaba cada dos por tres.\n\nTomás: Sí, era un caos. Desde que la señora Ortega creó un grupo de WhatsApp, todo va mejor.\n\nMarina: Pues yo al principio era bastante escéptica. Pensaba que sería otro chat para quejarse.\n\nTomás: Pues no. Ahí se publican los horarios, las rutas alternativas cuando nieva y hasta notas de voz del conductor.\n\nMarina: Lo que más me sorprende es que lo organizan entre todos. Los que tienen coche llevan a los niños cuando el autobús no sale.\n\nTomás: Exacto. Es una muestra de ingenio colectivo. Con un teléfono y algo de paciencia se resuelve un problema que parecía imposible.\n\nMarina: Aun así, hay gente mayor que no sabe usar el móvil y se queda fuera. Me parece un fallo importante.\n\nTomás: Tienes razón, pero la señora Ortega ya ha pedido a los jóvenes que les enseñen. Organizan clases los sábados en la biblioteca.\n\nMarina: Pues entonces va por buen camino. ¿Tú te apuntarías a dar una de esas clases?\n\nTomás: Claro, aunque reconozco que mi abuela me gana en paciencia.", "questions": [{"id": "human-ingenuity-gen-communication-online-3-q1", "type": "true-false", "prompt": "Al principio, Marina creía que el grupo de WhatsApp serviría solo para quejarse.", "correctAnswer": "true", "justification": "Pensaba que sería otro chat para quejarse."}, {"id": "human-ingenuity-gen-communication-online-3-q2", "type": "true-false", "prompt": "El autobús escolar de Valdeluz casi nunca se cancelaba.", "correctAnswer": "false", "justification": "Se cancelaba cada dos por tres."}, {"id": "human-ingenuity-gen-communication-online-3-q3", "type": "true-false", "prompt": "Los vecinos con coche ayudan a llevar a los niños cuando falla el autobús.", "correctAnswer": "true", "justification": "Los que tienen coche llevan a los niños cuando el autobús no sale."}, {"id": "human-ingenuity-gen-communication-online-3-q4", "type": "mcq", "prompt": "¿Qué opina Marina sobre las personas mayores que no saben usar el móvil?", "correctAnswer": "Le parece un fallo importante del sistema", "options": ["Le parece un fallo importante del sistema", "Cree que no necesitan aprender a usar el móvil", "Piensa que el grupo de WhatsApp debería cerrarse"]}, {"id": "human-ingenuity-gen-communication-online-3-q5", "type": "short", "prompt": "¿Cuándo se organizan las clases en la biblioteca?", "correctAnswer": "los sábados"}]},
  {"id": "human-ingenuity-gen-science-and-inventions-5", "themeId": "human-ingenuity", "title": "Un sensor para las abejas", "description": "Dos amigos discuten si un sensor inventado para vigilar colmenas es útil para un apicultor mayor.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: ¿Viste el artículo sobre el sensor para las colmenas? Mi abuelo lleva sesenta años cuidando abejas y dice que es una tontería.\n\nTomás: Pues yo creo que es una idea genial. El aparato mide la temperatura y la humedad dentro de la colmena, y te avisa al móvil si algo va mal.\n\nLucía: Ya, pero el abuelo dice que con oír a las abejas basta. Si zumban de otra manera, sabes que pasa algo.\n\nTomás: Eso lo entiendo, pero no siempre se nota a tiempo. El año pasado perdió tres colmenas por una plaga y se enteró cuando ya era tarde.\n\nLucía: Bueno, eso sí. Además, el sensor cuesta unos cien euros, que para él es mucho dinero.\n\nTomás: Sí, el precio es un problema. Pero la estudiante que lo diseñó dice que quiere venderlo más barato en los pueblos pequeños.\n\nLucía: Pues a ver si cumple. Yo, sinceramente, creo que la tecnología tiene que ayudar a la gente mayor, no complicarle la vida.\n\nTomás: Ahí tienes razón. Por eso le voy a proponer al abuelo que lo pruebe un mes y luego decida.", "questions": [{"id": "human-ingenuity-gen-science-and-inventions-5-q1", "type": "true-false", "prompt": "El sensor mide la temperatura y la humedad dentro de la colmena.", "correctAnswer": "true", "justification": "El aparato mide la temperatura y la humedad dentro de la colmena, y te avisa al móvil si algo va mal."}, {"id": "human-ingenuity-gen-science-and-inventions-5-q2", "type": "true-false", "prompt": "El abuelo de Lucía cree que el sensor es una gran idea.", "correctAnswer": "false", "justification": "Mi abuelo lleva sesenta años cuidando abejas y dice que es una tontería."}, {"id": "human-ingenuity-gen-science-and-inventions-5-q3", "type": "true-false", "prompt": "El abuelo de Lucía perdió tres colmenas a causa de una plaga.", "correctAnswer": "true", "justification": "El año pasado perdió tres colmenas por una plaga y se enteró cuando ya era tarde."}, {"id": "human-ingenuity-gen-science-and-inventions-5-q4", "type": "mcq", "prompt": "¿Por qué Tomás considera útil el sensor?", "correctAnswer": "Porque avisa a tiempo cuando hay un problema", "options": ["Porque avisa a tiempo cuando hay un problema", "Porque es más barato que otros aparatos", "Porque sustituye el trabajo de las abejas"]}]},
  {"id": "human-ingenuity-gen-entertainment-and-media-2", "themeId": "human-ingenuity", "title": "El ruido de la lluvia en la radio", "description": "Dos amigos comentan cómo un técnico de sonido de una radionovela mexicana crea efectos con objetos de cocina y qué opinan de ese trabajo.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Marina: ¿Ya escuchaste el capítulo nuevo de la radionovela de Puebla?\n\nTomás: Sí, y me quedé alucinado con el sonido de la lluvia. Parecía de verdad.\n\nMarina: Pues resulta que no hay ninguna grabadora de lluvia. El técnico de sonido, don Ernesto, la hace con arroz metido en una caja de cartón que gira despacio.\n\nTomás: ¡Qué ingenioso! ¿Y los pasos sobre la grava?\n\nMarina: Eso lo hace con zapatos viejos sobre una bandeja llena de maíz seco. Lleva años inventando efectos así.\n\nTomás: Pues a mí me parece una maravilla que con cosas de la cocina se logre tanto. Yo pensaba que hacían falta equipos carísimos.\n\nMarina: Pues yo no estoy tan convencida. Creo que los actores a veces exageran los gestos porque no ven nada, y el público se pierde un poco. Prefiero las grabaciones de antes.\n\nTomás: No sé, Marina, yo creo que la imaginación del oyente compensa todo. Además, hay un concurso la semana que viene para que la gente proponga sus efectos.\n\nMarina: Vale, eso sí me gusta. Me apunto con la idea de la sopa que hace ruido de trueno.\n\nTomás: ¡Ja! Tú sí que eres de las que inventan cosas raras.", "questions": [{"id": "human-ingenuity-gen-entertainment-and-media-2-q1", "type": "true-false", "prompt": "A Tomás le pareció realista el sonido de la lluvia de la radionovela.", "correctAnswer": "true", "justification": "Sí, y me quedé alucinado con el sonido de la lluvia."}, {"id": "human-ingenuity-gen-entertainment-and-media-2-q2", "type": "true-false", "prompt": "Los pasos sobre la grava se producen con zapatos nuevos sobre una tabla de madera.", "correctAnswer": "false", "justification": "Eso lo hace con zapatos viejos sobre una bandeja llena de maíz seco."}, {"id": "human-ingenuity-gen-entertainment-and-media-2-q3", "type": "mcq", "prompt": "¿Con qué materiales imita don Ernesto el sonido de la lluvia?", "correctAnswer": "arroz en una caja de cartón que gira despacio", "options": ["arroz en una caja de cartón que gira despacio", "agua que cae sobre una lata de metal", "una grabación real tomada en el campo"]}, {"id": "human-ingenuity-gen-entertainment-and-media-2-q4", "type": "short", "prompt": "¿Qué crítica hace Marina sobre los actores?", "correctAnswer": "exageran los gestos"}, {"id": "human-ingenuity-gen-entertainment-and-media-2-q5", "type": "mcq", "prompt": "¿Qué opina Tomás sobre los efectos hechos con objetos de cocina?", "correctAnswer": "Le parecen una maravilla de ingenio.", "options": ["Le parecen una maravilla de ingenio.", "Piensa que suenan poco creíbles.", "No les presta ninguna atención."]}]},
  {"id": "human-ingenuity-gen-transport-and-cities-4", "themeId": "human-ingenuity", "title": "La balsa que cruza el río", "description": "Un locutor y una periodista conversan sobre un pueblo que ideó una balsa sin motor para cruzar un río durante las inundaciones.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Hoy visitamos Puerto Lirio, un pueblo que queda aislado cada vez que sube el río.\n\nTomás: Así es. Cuando llueve en la sierra, el puente de madera queda bajo el agua durante semanas. Los niños tardaban casi dos horas en llegar a la escuela, dando un rodeo.\n\nLucía: Y entonces apareció la solución: una balsa que se mueve por un cable de acero.\n\nTomás: Exacto. La idea fue de don Efraín, un mecánico jubilado. No estudió ingeniería, pero conoce bien las poleas de su taller. Montó el cable de una orilla a otra y la balsa se desplaza tirando de él, sin motor.\n\nLucía: ¿Sin motor? ¿Cómo es posible?\n\nTomás: La corriente empuja la balsa en diagonal, y el cable la guía. Es como un columpio sobre el agua. Al principio mucha gente dudaba, pero ahora cruzan unas cuarenta personas cada mañana.\n\nLucía: Y ¿qué opinan los vecinos?\n\nTomás: Están orgullosos. Yo creo que es un ejemplo perfecto de ingenio: con materiales baratos resolvieron un problema que el gobierno tardó años en atender.\n\nLucía: Sin embargo, algunos dicen que el cable es peligroso en temporada de lluvias.\n\nTomás: Sí, por eso revisan el cable cada semana. La seguridad es lo primero, aunque reconozco que no todos están tranquilos.", "questions": [{"id": "human-ingenuity-gen-transport-and-cities-4-q1", "type": "true-false", "prompt": "Los niños llegaban a la escuela en menos de una hora.", "correctAnswer": "false", "justification": "Los niños tardaban casi dos horas en llegar a la escuela, dando un rodeo."}, {"id": "human-ingenuity-gen-transport-and-cities-4-q2", "type": "true-false", "prompt": "La balsa funciona sin motor.", "correctAnswer": "true", "justification": "Montó el cable de una orilla a otra y la balsa se desplaza tirando de él, sin motor."}, {"id": "human-ingenuity-gen-transport-and-cities-4-q3", "type": "mcq", "prompt": "¿Qué opina Tomás del proyecto de la balsa?", "correctAnswer": "Que es un ejemplo perfecto de ingenio", "options": ["Que es un ejemplo perfecto de ingenio", "Que es demasiado caro para el pueblo", "Que el gobierno debería construir un puente"]}, {"id": "human-ingenuity-gen-transport-and-cities-4-q4", "type": "mcq", "prompt": "¿Quién tuvo la idea de la balsa?", "correctAnswer": "Un mecánico jubilado", "options": ["Un mecánico jubilado", "Un ingeniero del gobierno", "Los niños de la escuela"]}, {"id": "human-ingenuity-gen-transport-and-cities-4-q5", "type": "short", "prompt": "¿Cuántas personas cruzan el río cada mañana?", "correctAnswer": "unas cuarenta"}]},
  {"id": "social-organization-gen-education-and-schools-1", "themeId": "social-organization", "title": "Clases de cocina en el barrio", "description": "Una alumna le presenta a su subdirector una propuesta para dar clases de cocina a los vecinos mayores del barrio.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Julia: Buenos días, profe. ¿Tiene un momento? Quería hablarle de la propuesta de las clases de cocina.\n\nSr. Ortega: Claro, Julia. Te escucho, aunque ya sabes que el presupuesto está muy ajustado.\n\nJulia: Lo sé, pero no pedimos dinero. Queremos que los alumnos de cuarto de la ESO den clases de cocina sencilla a los vecinos mayores del barrio los sábados por la mañana.\n\nSr. Ortega: Mmm... ¿Y quién se encarga de los permisos? Porque no es tan fácil como parece.\n\nJulia: Ya hablé con la asociación de vecinos. Ellos ponen la cocina del centro cívico, y nosotros, los voluntarios.\n\nSr. Ortega: Bueno, la idea me parece bonita, aunque tengo mis dudas sobre si los alumnos tienen tiempo con tantos exámenes.\n\nJulia: Por eso proponemos que sea solo una vez al mes. Y la verdad, muchos compañeros se quejan de que la escuela solo sirve para estudiar. Esto les daría algo distinto.\n\nSr. Ortega: Eso sí tiene sentido. Pero quiero que el primer mes lo supervise un profesor. Nada de improvisar.\n\nJulia: Perfecto. Entonces ¿podemos presentarlo al consejo escolar el próximo martes?\n\nSr. Ortega: Prepara un documento de una página con horarios y responsables. Si está bien, lo llevamos.", "questions": [{"id": "social-organization-gen-education-and-schools-1-q1", "type": "true-false", "prompt": "Los alumnos pedirán dinero al colegio para financiar el proyecto.", "correctAnswer": "false", "justification": "Lo sé, pero no pedimos dinero."}, {"id": "social-organization-gen-education-and-schools-1-q2", "type": "true-false", "prompt": "El primer mes, un profesor supervisará las clases.", "correctAnswer": "true", "justification": "Pero quiero que el primer mes lo supervise un profesor."}, {"id": "social-organization-gen-education-and-schools-1-q3", "type": "mcq", "prompt": "¿Qué opina Julia sobre la vida escolar?", "correctAnswer": "Cree que la escuela debería ofrecer algo más que estudiar", "options": ["Cree que la escuela debería ofrecer algo más que estudiar", "Cree que los exámenes son demasiado fáciles", "Piensa que la escuela no necesita ningún cambio"]}, {"id": "social-organization-gen-education-and-schools-1-q4", "type": "mcq", "prompt": "¿Dónde se impartirían las clases de cocina?", "correctAnswer": "En el centro cívico del barrio", "options": ["En el centro cívico del barrio", "En el gimnasio del instituto", "En la casa de un profesor"]}, {"id": "social-organization-gen-education-and-schools-1-q5", "type": "short", "prompt": "¿Con qué frecuencia quieren organizar las clases?", "correctAnswer": "una vez al mes"}]},
  {"id": "social-organization-gen-employment-and-first-jobs-2", "themeId": "social-organization", "title": "El cine de verano", "description": "Dos jóvenes conversan sobre el primer trabajo de verano de una de ellas en un cine al aire libre de un pueblo.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, Tomás, ¿qué tal el primer día en el cine de verano?\n\nTomás: Pues al principio me agobié, la verdad. El proyector es un cacharro y se atasca cada dos por tres.\n\nLucía: ¿Y la gente del pueblo? Dicen que son muy exigentes.\n\nTomás: Algunos se quejan si empieza tarde, pero la mayoría es muy maja. Lo mejor es que me pagan en efectivo cada viernes.\n\nLucía: Qué suerte. Yo quiero trabajar allí en agosto, pero mi madre dice que busque algo más serio.\n\nTomás: Pues no es tan poca cosa. Aprendes a organizarte y a tratar con gente de todas las edades. Eso en el currículum queda genial.\n\nLucía: Ya, pero mis amigas trabajan en una cadena de comida rápida y dicen que es mucho más moderno.\n\nTomás: Modernidad la justa. Yo prefiero estar al aire libre, con las estrellas encima y olor a palomitas.\n\nLucía: Vale, pues mañana hablo con el alcalde. Aunque cuadrar la caja al final de la noche me da pánico.\n\nTomás: Ya verás, con la práctica sale solo.", "questions": [{"id": "social-organization-gen-employment-and-first-jobs-2-q1", "type": "true-false", "prompt": "Tomás afirma que el proyector funciona sin problemas.", "correctAnswer": "false", "justification": "El proyector es un cacharro y se atasca cada dos por tres."}, {"id": "social-organization-gen-employment-and-first-jobs-2-q2", "type": "true-false", "prompt": "Tomás valora positivamente que le paguen en efectivo cada viernes.", "correctAnswer": "true", "justification": "Lo mejor es que me pagan en efectivo cada viernes."}, {"id": "social-organization-gen-employment-and-first-jobs-2-q3", "type": "mcq", "prompt": "¿Qué piensan las amigas de Lucía del trabajo en una cadena de comida rápida?", "correctAnswer": "Que es mucho más moderno.", "options": ["Que es mucho más moderno.", "Que es aburrido y mal pagado.", "Que es peligroso."]}, {"id": "social-organization-gen-employment-and-first-jobs-2-q4", "type": "short", "prompt": "¿Qué le da pánico a Lucía?", "correctAnswer": "cuadrar la caja"}, {"id": "social-organization-gen-employment-and-first-jobs-2-q5", "type": "true-false", "prompt": "Lucía ya habló con el alcalde hoy.", "correctAnswer": "false", "justification": "Vale, pues mañana hablo con el alcalde."}]},
  {"id": "human-ingenuity-gen-technology-and-innovation-6", "themeId": "human-ingenuity", "title": "Sensores entre las colmenas", "description": "Dos amigos discuten si los sensores electrónicos que vigilan las colmenas de los apicultores de la sierra son una ayuda útil o una exageración.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, ¿viste el reportaje sobre los apicultores de la sierra que usan sensores en las colmenas?\n\nTomás: Sí, lo vi anoche. Los sensores miden la temperatura y la humedad dentro de cada colmena, y envían los datos al móvil del apicultor.\n\nLucía: Pues a mí me parece una exageración. Las abejas llevan siglos sin necesitar un aparato para sobrevivir.\n\nTomás: Bueno, no es que las sustituyan. Según el reportaje, el año pasado muchas colonias murieron por el frío repentino, y con el aviso a tiempo los apicultores pudieron salvar buena parte.\n\nLucía: Vale, eso sí tiene sentido. Pero el problema es el precio. Un sensor cuesta casi lo mismo que una colmena entera.\n\nTomás: Es verdad, y a los pequeños productores les cuesta mucho. Pero una cooperativa de la zona compró varios juntos y los reparten entre los socios. Me parece una solución muy inteligente.\n\nLucía: Es buena idea, aunque yo sigo pensando que la tecnología no debería sustituir el conocimiento de toda la vida. Mi abuelo sabía leer el clima solo con oler el aire.\n\nTomás: Eso lo entiendo, pero creo que la combinación de experiencia y datos es lo mejor.", "questions": [{"id": "human-ingenuity-gen-technology-and-innovation-6-q1", "type": "true-false", "prompt": "Lucía considera que los sensores para las colmenas son una exageración.", "correctAnswer": "true", "justification": "Pues a mí me parece una exageración."}, {"id": "human-ingenuity-gen-technology-and-innovation-6-q2", "type": "true-false", "prompt": "Según Tomás, los sensores sustituyen completamente el trabajo de las abejas.", "correctAnswer": "false", "justification": "Bueno, no es que las sustituyan."}, {"id": "human-ingenuity-gen-technology-and-innovation-6-q3", "type": "mcq", "prompt": "¿Cuál es el problema que menciona Lucía sobre los sensores?", "correctAnswer": "El precio elevado de los sensores", "options": ["El precio elevado de los sensores", "La falta de electricidad en la sierra", "Las abejas que se niegan a entrar en las colmenas"]}, {"id": "human-ingenuity-gen-technology-and-innovation-6-q4", "type": "short", "prompt": "¿Qué hace la cooperativa con los sensores que compra?", "correctAnswer": "Repartirlos entre los socios"}, {"id": "human-ingenuity-gen-technology-and-innovation-6-q5", "type": "short", "prompt": "¿Qué piensa Tomás sobre combinar la experiencia con los datos?", "correctAnswer": "Que es lo mejor"}]},
  {"id": "social-organization-gen-community-life-and-volunteering-3", "themeId": "social-organization", "title": "Cacharros con segunda vida", "description": "Dos personas conversan sobre un taller de reparaciones voluntario que funciona los sábados en su barrio.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, Rubén, ¿y esto de arreglar cacharros los sábados es en serio? Pensaba que era un rollo de jubilados.\n\nRubén: Pues ya ves que no. Llevamos dos años y ya somos quince voluntarios, y la mitad tenemos menos de treinta.\n\nLucía: Vale, pero yo no sé nada de electrónica. Solo sé cambiar un fusible, y eso porque me lo enseñó mi padre.\n\nRubén: Tranquila, que nadie te pide que seas técnico. Aquí se aprende haciendo. El que sabe soldar enseña al que no, y así.\n\nLucía: ¿Y la gente trae de todo? Me imagino tostadoras, aspiradoras...\n\nRubén: De todo. El mes pasado arreglamos una cafetera de los años setenta. La señora casi llora cuando la vio funcionar.\n\nLucía: Qué bonito. Pero oye, ¿no sería más útil dar clases en un colegio o algo así?\n\nRubén: Puede ser, pero para mí lo importante es que la gente aprenda que muchas cosas no hay que tirarlas. Yo creo que eso también es educar.\n\nLucía: Pues tienes razón. Me apunto el próximo sábado, aunque sea para traer el café.\n\nRubén: Jajaja, trae galletas, que las de aquí son malísimas.", "questions": [{"id": "social-organization-gen-community-life-and-volunteering-3-q1", "type": "true-false", "prompt": "La mitad de los voluntarios tiene menos de treinta años.", "correctAnswer": "true", "justification": "Llevamos dos años y ya somos quince voluntarios, y la mitad tenemos menos de treinta."}, {"id": "social-organization-gen-community-life-and-volunteering-3-q2", "type": "true-false", "prompt": "Lucía tiene mucha experiencia con la electrónica.", "correctAnswer": "false", "justification": "Vale, pero yo no sé nada de electrónica."}, {"id": "social-organization-gen-community-life-and-volunteering-3-q3", "type": "true-false", "prompt": "Rubén opina que el taller también sirve para educar.", "correctAnswer": "true", "justification": "Yo creo que eso también es educar."}, {"id": "social-organization-gen-community-life-and-volunteering-3-q4", "type": "mcq", "prompt": "¿Qué piensa Lucía al principio sobre el taller?", "correctAnswer": "Que es una actividad solo para jubilados", "options": ["Que es una actividad solo para jubilados", "Que es demasiado caro", "Que el café es malísimo"]}, {"id": "social-organization-gen-community-life-and-volunteering-3-q5", "type": "short", "prompt": "¿Qué aparato arreglaron el mes pasado?", "correctAnswer": "una cafetera"}]},
  {"id": "social-organization-gen-relationships-and-friendship-4", "themeId": "social-organization", "title": "Los tomates del huerto", "description": "Dos vecinos discuten por el turno de riego de su huerto urbano y reconstruyen su amistad.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Carmen: Oye, Tomás, ¿tienes un minuto? Quiero hablar de lo del huerto.\n\nTomás: Claro, dime. Si es por los tomates, ya sé que me pasé.\n\nCarmen: Pues sí. Me molestó que cambiaras el turno de riego sin preguntarme.\n\nTomás: Pensé que te daba igual, porque siempre estás de viaje los fines de semana.\n\nCarmen: Pues no me da igual. Este huerto es lo único que me hace salir de casa los domingos.\n\nTomás: Uf, no lo sabía. Perdona de verdad. Llevamos tres años compartiendo huerto y nunca me lo habías dicho.\n\nCarmen: Ya, pero no te lo dije antes porque me daba vergüenza. Desde que se fue Pablo a Valencia me siento un poco sola.\n\nTomás: Pues cuenta conmigo los domingos. Si quieres, desayunamos aquí después de regar.\n\nCarmen: Me parece genial. Creo que la amistad se mantiene precisamente hablando de estas cosas, aunque cueste.\n\nTomás: Totalmente de acuerdo. Entonces, el turno de riego lo hacemos juntos, ¿no?\n\nCarmen: Trato hecho. Y los tomates, déjalos en paz.", "questions": [{"id": "social-organization-gen-relationships-and-friendship-4-q1", "type": "true-false", "prompt": "Tomás cambió el turno de riego sin consultar a Carmen.", "correctAnswer": "true", "justification": "Me molestó que cambiaras el turno de riego sin preguntarme."}, {"id": "social-organization-gen-relationships-and-friendship-4-q2", "type": "true-false", "prompt": "Carmen se siente sola desde que Tomás se fue a vivir a Valencia.", "correctAnswer": "false", "justification": "Desde que se fue Pablo a Valencia me siento un poco sola."}, {"id": "social-organization-gen-relationships-and-friendship-4-q3", "type": "mcq", "prompt": "¿Qué opina Carmen sobre la amistad?", "correctAnswer": "Que se mantiene hablando de los problemas, aunque cueste", "options": ["Que se mantiene hablando de los problemas, aunque cueste", "Que es mejor no discutir nunca", "Que depende únicamente del huerto"]}, {"id": "social-organization-gen-relationships-and-friendship-4-q4", "type": "short", "prompt": "¿Qué propone Tomás para los domingos?", "correctAnswer": "desayunar juntos"}]},
  {"id": "social-organization-gen-education-and-schools-6", "themeId": "social-organization", "title": "Una escuela que podría cerrar", "description": "Dos vecinos de un pueblo hablan sobre el riesgo de cierre de su colegio y sobre posibles soluciones para mantenerlo abierto.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Lucía: Buenos días, Javier. ¿Has leído la carta de la Consejería? Dicen que el colegio de Valdeluz podría cerrar si no llegamos a doce alumnos.\n\nJavier: Sí, la vi ayer. Es una barbaridad. Mi hija va a cuarto y en su clase solo son cuatro. El problema no es la escuela, es que no hay trabajo para los jóvenes.\n\nLucía: Estoy de acuerdo en parte, pero los niños aprenden mejor en grupos pequeños. En la ciudad, con treinta en clase, es imposible.\n\nJavier: Ya, pero el autobús tarda cuarenta minutos y los niños llegan agotados.\n\nLucía: Por eso proponemos abrir el colegio a los adultos por las tardes, con clases de informática e idiomas. Así la gente se queda en el pueblo.\n\nJavier: Me parece buena idea, aunque dudo que el ayuntamiento se implique. Llevan años prometiendo cosas.\n\nLucía: Lo sé, pero esta vez tenemos firmas de treinta familias. Nadie quiere perder la escuela.\n\nJavier: Pues cuenta conmigo. Mañana hablo con el alcalde y le digo que doy clases de carpintería los sábados.\n\nLucía: ¡Qué bien! Te lo agradezco mucho.", "questions": [{"id": "social-organization-gen-education-and-schools-6-q1", "type": "true-false", "prompt": "Según Javier, el problema del colegio es la falta de trabajo en la zona.", "correctAnswer": "true", "justification": "El problema no es la escuela, es que no hay trabajo para los jóvenes."}, {"id": "social-organization-gen-education-and-schools-6-q2", "type": "true-false", "prompt": "El autobús tarda veinte minutos en llegar al colegio.", "correctAnswer": "false", "justification": "Ya, pero el autobús tarda cuarenta minutos y los niños llegan agotados."}, {"id": "social-organization-gen-education-and-schools-6-q3", "type": "mcq", "prompt": "¿Qué opina Javier sobre el ayuntamiento?", "correctAnswer": "Duda que el ayuntamiento se implique", "options": ["Duda que el ayuntamiento se implique", "Está seguro de que el ayuntamiento ayudará", "Quiere cerrar el colegio cuanto antes"]}, {"id": "social-organization-gen-education-and-schools-6-q4", "type": "short", "prompt": "¿Qué ofrece Javier para ayudar al colegio?", "correctAnswer": "clases de carpintería"}, {"id": "social-organization-gen-education-and-schools-6-q5", "type": "short", "prompt": "¿Cuántas familias han firmado la petición?", "correctAnswer": "treinta"}]},
  {"id": "sharing-planet-gen-environment-and-climate-1", "themeId": "sharing-planet", "title": "El glaciar que se va", "description": "Dos amigos hablan sobre el retroceso de un glaciar de montaña y sus consecuencias para los pueblos y el turismo.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye Tomás, ¿viste lo que dijeron ayer en la radio sobre el glaciar? Ya no llega ni a la mitad del mirador de hace diez años.\n\nTomás: Sí, lo vi. Llevo quince años con este refugio y el cambio se nota un montón. El arroyo de detrás ahora baja con el doble de agua en verano.\n\nLucía: Por eso me preocupa. Si el hielo se derrite tan rápido, el agua se acabará en unos años. Los pueblos de abajo dependen de ese caudal.\n\nTomás: Los expertos exageran un poco, ¿no? Sigue nevando en invierno, solo que menos.\n\nLucía: Pues yo no lo veo como exageración. Mira estas fotos de cuando yo era niña. Eran paisajes totalmente distintos.\n\nTomás: Vale, te doy la razón en que hay que hacer algo. Lo que no me convence es que el gobierno se lo tome en serio solo cuando sale en las noticias.\n\nLucía: Ahí sí estamos de acuerdo. El año que viene quiero organizar una ruta guiada para explicar el problema a los turistas.\n\nTomás: Buena idea. Pero que no sea solo para sacar fotos, ¿eh?", "questions": [{"id": "sharing-planet-gen-environment-and-climate-1-q1", "type": "true-false", "prompt": "El glaciar ocupa ahora más terreno que hace diez años.", "correctAnswer": "false", "justification": "Ya no llega ni a la mitad del mirador de hace diez años."}, {"id": "sharing-planet-gen-environment-and-climate-1-q2", "type": "true-false", "prompt": "El arroyo lleva más agua en verano que antes.", "correctAnswer": "true", "justification": "El arroyo de detrás ahora baja con el doble de agua en verano."}, {"id": "sharing-planet-gen-environment-and-climate-1-q3", "type": "mcq", "prompt": "¿Qué opina Tomás sobre los expertos?", "correctAnswer": "Cree que exageran un poco.", "options": ["Cree que exageran un poco.", "Está totalmente de acuerdo con ellos.", "No sabe nada del tema."]}, {"id": "sharing-planet-gen-environment-and-climate-1-q4", "type": "short", "prompt": "¿De qué dependen los pueblos de abajo?", "correctAnswer": "el caudal de agua"}, {"id": "sharing-planet-gen-environment-and-climate-1-q5", "type": "short", "prompt": "¿Qué quiere organizar Lucía el año que viene?", "correctAnswer": "una ruta guiada"}]},
  {"id": "social-organization-gen-law-rights-and-voting-5", "themeId": "social-organization", "title": "Consulta en el barrio", "description": "Dos vecinos comentan una consulta municipal sobre los pisos turísticos de su barrio y discuten quién puede participar y si el resultado es vinculante.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, ¿te has enterado de la consulta vecinal del martes? Podemos votar sobre los pisos turísticos.\n\nTomás: Sí, lo vi en el tablón. Pero solo tengo diecisiete años, no sé si cuento.\n\nLucía: Según el folleto, cualquier persona empadronada de dieciséis años en adelante puede participar.\n\nTomás: Vale. ¿Y el resultado es obligatorio para el ayuntamiento?\n\nLucía: No es vinculante, pero a mí me parece importante que la gente opine.\n\nTomás: Yo creo que es una pérdida de tiempo. Al final, nadie obliga a los dueños a nada.\n\nLucía: No estoy de acuerdo. Mi abuela perdió a su vecina de toda la vida porque el edificio entero se convirtió en apartamentos turísticos.\n\nTomás: Bueno, visto así... Pero si tienes un piso, deberías poder alquilarlo como quieras, ¿no?\n\nLucía: Hasta cierto punto. Cuando afecta a la convivencia, hay que hablarlo entre todos.\n\nTomás: Vale, me has convencido. ¿Quedamos el martes a las seis en el centro cívico?\n\nLucía: Perfecto. Y no olvides el DNI, que sin él no te dejan votar.\n\nTomás: Tranquila, lo llevo siempre encima.", "questions": [{"id": "social-organization-gen-law-rights-and-voting-5-q1", "type": "true-false", "prompt": "Tomás tiene dieciocho años.", "correctAnswer": "false", "justification": "Pero solo tengo diecisiete años, no sé si cuento."}, {"id": "social-organization-gen-law-rights-and-voting-5-q2", "type": "true-false", "prompt": "El resultado de la consulta es obligatorio para el ayuntamiento.", "correctAnswer": "false", "justification": "No es vinculante, pero a mí me parece importante que la gente opine."}, {"id": "social-organization-gen-law-rights-and-voting-5-q3", "type": "mcq", "prompt": "¿Qué opina Tomás sobre la consulta vecinal?", "correctAnswer": "Cree que es una pérdida de tiempo.", "options": ["Cree que es una pérdida de tiempo.", "Cree que la consulta es muy importante.", "Cree que solo deben votar los propietarios."]}, {"id": "social-organization-gen-law-rights-and-voting-5-q4", "type": "short", "prompt": "¿Qué documento necesita Tomás para votar?", "correctAnswer": "DNI"}, {"id": "social-organization-gen-law-rights-and-voting-5-q5", "type": "short", "prompt": "¿Qué le pasó al edificio de la abuela de Lucía?", "correctAnswer": "apartamentos turísticos"}]},
  {"id": "sharing-planet-gen-consumption-and-recycling-2", "themeId": "sharing-planet", "title": "Arreglar en vez de tirar", "description": "Dos amigos comentan su experiencia en un café de reparaciones de su barrio y reflexionan sobre por qué la gente compra aparatos nuevos en lugar de arreglar los viejos.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, ¿fuiste ayer al café de reparaciones? Yo llevé la batidora de mi abuela y la arreglaron en veinte minutos.\n\nTomás: Sí, llevé una radio que llevaba años en el trastero. Un voluntario jubilado me la dejó como nueva y no me cobró nada.\n\nLucía: Qué bien. Yo pensaba que esos sitios eran solo para gente con poco dinero.\n\nTomás: Pues hay de todo. Lo que más me sorprendió es que hay un chico que trae el portátil de su hermana cada semana para aprender a arreglarlo.\n\nLucía: Me parece una idea genial. Mi móvil tiene la batería hecha polvo y lo tengo guardado en un cajón. Pienso llevarlo.\n\nTomás: Claro, cuesta menos que comprar uno nuevo y se genera menos basura. Eso sí, hay que apuntarse con antelación, porque las plazas vuelan.\n\nLucía: Pues apúntame para el próximo. Y si no tiene arreglo, al menos te explican cómo reciclarlo bien.\n\nTomás: Exacto. Lo que no entiendo es por qué la gente cambia de móvil cada año.\n\nLucía: Pues por la publicidad, supongo. Yo también caí el año pasado.", "questions": [{"id": "sharing-planet-gen-consumption-and-recycling-2-q1", "type": "true-false", "prompt": "Lucía llevó al café de reparaciones la batidora de su abuela.", "correctAnswer": "true", "justification": "Yo llevé la batidora de mi abuela y la arreglaron en veinte minutos."}, {"id": "sharing-planet-gen-consumption-and-recycling-2-q2", "type": "true-false", "prompt": "El voluntario le cobró a Tomás por arreglar la radio.", "correctAnswer": "false", "justification": "Un voluntario jubilado me la dejó como nueva y no me cobró nada."}, {"id": "sharing-planet-gen-consumption-and-recycling-2-q3", "type": "mcq", "prompt": "¿Qué opina Lucía de la idea del café de reparaciones?", "correctAnswer": "Le parece genial", "options": ["Le parece genial", "Le parece cara", "No le interesa"]}, {"id": "sharing-planet-gen-consumption-and-recycling-2-q4", "type": "short", "prompt": "¿Qué problema tiene el móvil de Lucía?", "correctAnswer": "la batería"}]},
  {"id": "sharing-planet-gen-globalisation-and-cultures-5", "themeId": "sharing-planet", "title": "Chales que cruzan el mundo", "description": "Una tejedora y su sobrino discuten si vender sus chales por internet a clientes de otros países ayuda o amenaza la tradición de su comunidad.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Rosa: Iván, ¿ya subiste las fotos de los chales nuevos a la tienda en línea? Hay pedidos de Japón y de Alemania.\n\nIván: Sí, tía, ya está todo. Me sorprende cuánta gente quiere comprar algo tan artesanal desde tan lejos.\n\nRosa: A mí me encanta que nuestros tejidos viajen. Mi abuela nunca imaginó que sus diseños llegarían a otro continente.\n\nIván: Claro, pero a veces siento que estamos vendiendo una imagen. Los turistas quieren la foto con el telar, no el trabajo de horas.\n\nRosa: Eso es verdad, pero el dinero nos permite pagar la escuela de los niños y comprar lana de mejor calidad.\n\nIván: Ya lo sé. Solo digo que deberíamos explicar en cada envío quién tejió la prenda y de qué comunidad viene.\n\nRosa: Buena idea. Eso sí es respeto. Hagamos una tarjeta con el nombre de cada tejedora.\n\nIván: Perfecto. Así la globalización no nos borra, ¿no?\n\nRosa: Exacto. Mientras la gente sepa de dónde viene el chal, nos conviene vender más allá de la plaza.", "questions": [{"id": "sharing-planet-gen-globalisation-and-cultures-5-q1", "type": "true-false", "prompt": "Iván cree que los turistas valoran más el trabajo de las tejedoras que la foto.", "correctAnswer": "false", "justification": "Los turistas quieren la foto con el telar, no el trabajo de horas."}, {"id": "sharing-planet-gen-globalisation-and-cultures-5-q2", "type": "true-false", "prompt": "Rosa cree que las ventas permiten pagar la escuela de los niños.", "correctAnswer": "true", "justification": "el dinero nos permite pagar la escuela de los niños y comprar lana de mejor calidad."}, {"id": "sharing-planet-gen-globalisation-and-cultures-5-q3", "type": "mcq", "prompt": "¿Qué propone Iván para cada envío?", "correctAnswer": "Explicar quién tejió cada prenda y de qué comunidad viene", "options": ["Explicar quién tejió cada prenda y de qué comunidad viene", "Ofrecer descuentos para los clientes de Japón", "Enviar los pedidos más rápido por avión"]}, {"id": "sharing-planet-gen-globalisation-and-cultures-5-q4", "type": "short", "prompt": "¿Qué siente Rosa cuando sus tejidos viajan a otros países?", "correctAnswer": "le encanta"}, {"id": "sharing-planet-gen-globalisation-and-cultures-5-q5", "type": "short", "prompt": "¿Qué quiere hacer Rosa para mostrar el nombre de cada tejedora?", "correctAnswer": "una tarjeta"}]},
  {"id": "sharing-planet-gen-human-rights-3", "themeId": "sharing-planet", "title": "Comida que no se tira", "description": "Dos vecinos discuten si las donaciones de un supermercado al banco de alimentos del barrio son suficientes para garantizar el derecho a la alimentación.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Lucía: Oye, Diego, ¿te acuerdas de que el supermercado de la esquina tiraba la comida que no se vendía?\n\nDiego: Sí, claro. Pensaba que era normal, la verdad. Si ya no sirve para vender, ¿qué más da?\n\nLucía: Pues da mucho. Hay gente en el barrio que no tiene para comer todos los días, y ahora el supermercado nos da el pan y las frutas que aún están buenas. Yo creo que el derecho a la alimentación debería ser una prioridad.\n\nDiego: Vale, pero no me parece justo que la empresa cargue con todo. ¿Quién paga si alguien se pone enfermo por algo que comió?\n\nLucía: Por eso hay una ley que protege a quien dona de buena fe. Además, el año pasado se tiraron toneladas de comida en la ciudad. Es un despropósito.\n\nDiego: Tienes razón en lo del desperdicio. Lo que me preocupa es que el banco de alimentos dependa de donaciones y no de un derecho garantizado por el Estado.\n\nLucía: Eso también es cierto, pero mientras tanto, prefiero que la comida llegue a una familia que a la basura.\n\nDiego: Pues sí, en eso estamos de acuerdo. Mañana me paso por el local y os ayudo a clasificar.\n\nLucía: ¡Genial! Empezamos a las ocho, que a esa hora llega el camión.", "questions": [{"id": "sharing-planet-gen-human-rights-3-q1", "type": "true-false", "prompt": "Según Lucía, el supermercado ya regala pan y fruta a los vecinos.", "correctAnswer": "true", "justification": "ahora el supermercado nos da el pan y las frutas que aún están buenas."}, {"id": "sharing-planet-gen-human-rights-3-q2", "type": "true-false", "prompt": "Diego cree que la empresa debe asumir toda la responsabilidad.", "correctAnswer": "false", "justification": "no me parece justo que la empresa cargue con todo."}, {"id": "sharing-planet-gen-human-rights-3-q3", "type": "mcq", "prompt": "¿Cuál es la principal preocupación de Diego sobre el banco de alimentos?", "correctAnswer": "que el banco de alimentos dependa de donaciones y no de un derecho garantizado por el Estado", "options": ["que el banco de alimentos dependa de donaciones y no de un derecho garantizado por el Estado", "que la comida esté en mal estado", "que el camión llegue demasiado tarde"]}, {"id": "sharing-planet-gen-human-rights-3-q4", "type": "short", "prompt": "¿Qué cree Lucía que debería ser una prioridad?", "correctAnswer": "el derecho a la alimentación"}, {"id": "sharing-planet-gen-human-rights-3-q5", "type": "true-false", "prompt": "Diego va a ayudar a clasificar la comida al día siguiente.", "correctAnswer": "true", "justification": "Mañana me paso por el local y os ayudo a clasificar."}]},
  {"id": "sharing-planet-gen-peace-and-conflict-4", "themeId": "sharing-planet", "title": "El agua que nos une", "description": "Un mediador comunitario explica en la radio cómo dos pueblos vecinos resolvieron años de disputas por el agua de un río.", "level": "medium", "durationLabel": "~9 min", "bodyEs": "Lucía: Bienvenidos a \"Voces del valle\". Hoy hablamos con Ramón Ortiz, mediador comunitario, sobre el conflicto del río Tamarón entre los pueblos de Villanueva y San Pedro.\n\nRamón: Gracias, Lucía. La verdad es que la situación era muy tensa. Durante años, los dos pueblos se pelearon por el agua para regar, y hubo hasta amenazas y cortes de la acequia.\n\nLucía: ¿Y cómo lograron ponerse de acuerdo?\n\nRamón: Creamos una comisión mixta con representantes de ambos lados. Al principio nadie quería ni sentarse en la misma mesa. Pero poco a poco, la gente empezó a escucharse de verdad.\n\nLucía: ¿Tú crees que el acuerdo va a durar?\n\nRamón: Sinceramente, sí. Ahora hay turnos fijos de riego, y eso quita muchas excusas para pelear. Además, los niños de los dos pueblos juegan juntos en la misma escuela.\n\nLucía: Hay quien dice que todo esto es demasiado optimista.\n\nRamón: Entiendo el escepticismo, pero yo pienso que la paz no empieza con grandes discursos, sino con cosas prácticas, como compartir una acequia.", "questions": [{"id": "sharing-planet-gen-peace-and-conflict-4-q1", "type": "true-false", "prompt": "Los dos pueblos llevan años sin pelearse por el agua.", "correctAnswer": "false", "justification": "Durante años, los dos pueblos se pelearon por el agua para regar, y hubo hasta amenazas y cortes de la acequia."}, {"id": "sharing-planet-gen-peace-and-conflict-4-q2", "type": "true-false", "prompt": "Hoy existen turnos fijos para regar el campo.", "correctAnswer": "true", "justification": "Ahora hay turnos fijos de riego, y eso quita muchas excusas para pelear."}, {"id": "sharing-planet-gen-peace-and-conflict-4-q3", "type": "mcq", "prompt": "¿Qué opina Ramón sobre la durabilidad del acuerdo?", "correctAnswer": "Que el acuerdo va a durar", "options": ["Que el acuerdo va a durar", "Que el acuerdo fracasará pronto", "Que no quiere opinar sobre el acuerdo"]}, {"id": "sharing-planet-gen-peace-and-conflict-4-q4", "type": "mcq", "prompt": "Según Ramón, ¿qué ayuda más a conseguir la paz?", "correctAnswer": "Cosas prácticas, como compartir una acequia", "options": ["Cosas prácticas, como compartir una acequia", "Grandes discursos en la capital", "Acuerdos firmados solo por los políticos"]}, {"id": "sharing-planet-gen-peace-and-conflict-4-q5", "type": "short", "prompt": "¿Dónde juegan juntos los niños de los dos pueblos?", "correctAnswer": "en la misma escuela"}]},
  {"id": "sharing-planet-gen-environment-and-climate-6", "themeId": "sharing-planet", "title": "La plaga de medusas", "description": "Un pescador y una bióloga marina debaten sobre la proliferación de medusas en la costa, sus causas y las posibles soluciones.", "level": "hard", "durationLabel": "~9 min", "bodyEs": "Tomás: Lucía, ¿has visto la playa de Cala Azul? Esta mañana no había ni un bañista.\n\nLucía: Sí, las medusas otra vez. Llevamos tres semanas así. Es un desastre para el turismo.\n\nTomás: Y para nosotros, los pescadores. Las redes se llenan de medusas y no pescamos nada. Yo creo que el gobierno debería pagarnos las pérdidas, porque nosotros no tenemos la culpa.\n\nLucía: Pues a mí me parece que la culpa es nuestra, en parte. Hemos pescado tanto atún que los depredadores de las medusas casi han desaparecido. Y encima el agua está más caliente.\n\nTomás: Puede ser, pero eso es muy largo de arreglar. Mientras tanto, ¿qué hacemos? Yo al menos quiero una solución rápida, como barreras flotantes.\n\nLucía: Las barreras ayudan en una playa, pero no en todo el mar. Yo prefiero proteger a los animales que se comen las medusas. Es la solución a largo plazo.\n\nTomás: Bueno, tú lo ves desde el laboratorio. Yo lo veo desde el barco, y ahí no hay paciencia que valga.\n\nLucía: Lo entiendo, de verdad. Pero si no cambiamos el modo de pescar, esto va a volver cada verano.", "questions": [{"id": "sharing-planet-gen-environment-and-climate-6-q1", "type": "true-false", "prompt": "Tomás explica que sus redes se llenan de medusas y que no consiguen pescar nada.", "correctAnswer": "true", "justification": "Las redes se llenan de medusas y no pescamos nada."}, {"id": "sharing-planet-gen-environment-and-climate-6-q2", "type": "true-false", "prompt": "Lucía cree que la culpa de la plaga de medusas es solo de los pescadores.", "correctAnswer": "false", "justification": "Pues a mí me parece que la culpa es nuestra, en parte."}, {"id": "sharing-planet-gen-environment-and-climate-6-q3", "type": "mcq", "prompt": "¿Qué opina Tomás sobre la responsabilidad del gobierno?", "correctAnswer": "Debería pagar a los pescadores por las pérdidas.", "options": ["Debería pagar a los pescadores por las pérdidas.", "Debería prohibir la pesca durante todo el año.", "No debería intervenir, porque es un problema natural."]}, {"id": "sharing-planet-gen-environment-and-climate-6-q4", "type": "short", "prompt": "¿Cuántas semanas llevan con el problema de las medusas en la playa?", "correctAnswer": "tres semanas"}]},
];
